#include <stdint.h>

#include "stm32f407xx.h"

extern uint32_t systemTimeCounter;


void delayMs(uint32_t delay)
{
	uint32_t curr = systemTimeCounter;
	while(systemTimeCounter - curr < delay)
	{	}
}

void i2cTransmit(
		uint8_t addr,
		uint8_t *data,
		uint8_t count){

	I2C3->CR1 |=  I2C_CR1_START;

	while (!(I2C3->SR1 & I2C_SR1_SB)){}

	uint8_t temp = I2C3->SR1;
	I2C3->DR = addr << 1;

	while (!(I2C3->SR1 & I2C_SR1_ADDR) ){}

	uint8_t temp2 = I2C3->SR1;
	uint8_t temp3 = I2C3->SR2;

	for (int i = 0; i < count; i++){
		I2C3->DR = data[i];
		while (!(I2C3->SR1 & I2C_SR1_TXE)){}
		while (!(I2C3->SR1 & I2C_SR1_BTF)){}
	}


	I2C3->CR1 |=  I2C_CR1_STOP;

}
void spiTransmitRecieve(uint8_t *td,uint8_t tn, uint8_t *rd, uint8_t rn){
	GPIOC->ODR &= ~GPIO_ODR_ODR_7;
	uint8_t dummy;
	for (int i = 0 ; i < tn; i++){
		while(!(SPI3->SR & SPI_SR_TXE));
		SPI3->DR = td[i];
		while(!(SPI3->SR & SPI_SR_RXNE));
		dummy = SPI3->DR;
	}


	while (SPI3->SR & SPI_SR_BSY);
		for (int i = 0 ; i < rn; i++){
			while(!(SPI3->SR & SPI_SR_TXE));
			SPI3->DR = dummy;
			while(!(SPI3->SR & SPI_SR_RXNE));
			rd[i] = SPI3->DR;
				}
		while (SPI3->SR & SPI_SR_BSY);
	GPIOC->ODR |= GPIO_ODR_ODR_7;
}
